1	/**
2	 * Shared-hosting primitives (Phase 1 foundation).
3	 *
4	 * Pure, framework-free helpers the account lifecycle is built on — unit-tested so
5	 * the parts that end up in a shell command on a MULTI-TENANT box (a username, a
6	 * quota, a domain in an nginx `server_name`) are provably well-formed before they
7	 * ever get there. On a shared box a single bad interpolation is not one
8	 * customer's bug, it is everyone's; these validators are the first line of that.
9	 */
10	
11	/** A syntactically valid domain for a name-based vhost (no scheme, no path). */
12	const DOMAIN_RE = /^(?=.{1,253}$)([a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$/;
13	
14	/** True for a hostname safe to place in an nginx `server_name` / a cert request. */
15	export function isValidHostingDomain(domain: string): boolean {
16	  const d = String(domain ?? "").trim().toLowerCase().replace(/\.$/, "");
17	  return DOMAIN_RE.test(d);
18	}
19	
20	export function normalizeHostingDomain(domain: string): string {
21	  return String(domain ?? "").trim().toLowerCase().replace(/^www\./, "").replace(/\.$/, "");
22	}
23	
24	/**
25	 * A safe jailed Linux username for an account, derived deterministically and kept
26	 * short (Linux caps usernames at 32 chars; some tooling chokes past 16). Starts
27	 * with a letter, lowercase alnum only — nothing a shell could ever interpret.
28	 *
29	 * `seed` (email localpart or account id) proposes a readable base; `disambiguator`
30	 * (a slice of the account id) guarantees per-node uniqueness without a DB probe.
31	 * The result still has to pass `isValidUnixUsername` before use, and the caller
32	 * resolves any residual collision against the DB (`@@unique([hostingNodeId, username])`).
33	 */
34	export function deriveUsername(seed: string, disambiguator: string): string {
35	  const base = String(seed ?? "")
36	    .toLowerCase()
37	    .replace(/[^a-z0-9]/g, "")
38	    .replace(/^[0-9]+/, "") // must not start with a digit
39	    .slice(0, 8);
40	  const suffix = String(disambiguator ?? "")
41	    .toLowerCase()
42	    .replace(/[^a-z0-9]/g, "")
43	    .slice(0, 6);
44	  // Guarantee a non-empty body so the result always clears the min-length rule
45	  // even when both inputs sanitise away to nothing.
46	  const body = `${base}${suffix}` || "acct";
47	  return `nx${body}`.slice(0, 16);
48	}
49	
50	const UNIX_USER_RE = /^[a-z][a-z0-9]{2,31}$/;
51	
52	/** True only for a shell-inert, policy-valid Linux username. */
53	export function isValidUnixUsername(name: string): boolean {
54	  return UNIX_USER_RE.test(String(name ?? ""));
55	}
56	
57	export type HostingPlanLimits = {
58	  diskGB: number;
59	  maxSites: number;
60	  maxDatabases: number;
61	  bandwidthTB: number;
62	  phpVersions: string[];
63	};
64	
65	/** The effective, sanitised limits for an account, snapshotted from its plan. */
66	export function planLimits(plan: {
67	  diskGB: number;
68	  maxSites: number;
69	  maxDatabases: number;
70	  bandwidthTB: number;
71	  phpVersions: string;
72	}): HostingPlanLimits {
73	  const php = String(plan.phpVersions ?? "")
74	    .split(",")
75	    .map((v) => v.trim())
76	    .filter((v) => /^\d\.\d$/.test(v));
77	  return {
78	    diskGB: Math.max(1, Math.floor(plan.diskGB || 1)),
79	    maxSites: Math.max(1, Math.floor(plan.maxSites || 1)),
80	    maxDatabases: Math.max(0, Math.floor(plan.maxDatabases || 0)),
81	    bandwidthTB: Math.max(0, plan.bandwidthTB || 0),
82	    phpVersions: php.length ? php : ["8.3"],
83	  };
84	}
85	
86	/** Disk quota in KB blocks for `setquota` (1 GB = 1,048,576 one-KB blocks). */
87	export function diskQuotaBlocks(diskGB: number): number {
88	  return Math.max(1, Math.floor(diskGB)) * 1024 * 1024;
89	}
90	
91	/**
92	 * What the customer sets in DNS to point a domain at their account: an A record
93	 * to the node's shared public IP. (A CNAME to the node FQDN is offered too when
94	 * the node has one, for sub-domains / apex-ALIAS providers.)
95	 */
96	export function pointToRecords(node: { publicIp: string; hostnameFqdn?: string | null }): {
97	  aRecord: string;
98	  cnameTarget: string | null;
99	} {
100	  return { aRecord: node.publicIp, cnameTarget: node.hostnameFqdn?.trim() || null };
101	}
102	
103	/** The absolute home + web root for an account's jailed user. */
104	export function accountPaths(username: string): { home: string; webroot: string; fpmPool: string } {
105	  return {
106	    home: `/home/${username}`,
107	    webroot: `/home/${username}/public_html`,
108	    fpmPool: `/etc/php/fpm-pools/${username}.conf`,
109	  };
110	}
111	
112	/**
113	 * Per-account directory holding the self-signed FALLBACK cert generated at
114	 * provision time (fullchain.pem + privkey.pem). Its whole purpose: nginx can
115	 * `listen 443 ssl` from the moment the account exists, so HTTPS shows a cert
116	 * WARNING, never ERR_CONNECTION_REFUSED — the real Let's Encrypt cert replaces it
117	 * once the SSL sweep issues one. Username is already validated before this reaches
118	 * a shell (isValidUnixUsername), same as accountPaths. */
119	export function selfSignedCertDir(username: string): string {
120	  return `/etc/ssl/hosting/${username}`;
121	}
122	
123	/**
124	 * A single DNS label for a subdomain (the part left of the primary domain, e.g.
125	 * "shop" in shop.example.com). No dots — a subdomain is exactly one label deep;
126	 * lowercase alnum + internal hyphens only, so it is shell-inert AND a valid
127	 * hostname label + directory name.
128	 */
129	const SUB_LABEL_RE = /^[a-z0-9](?:[a-z0-9-]{0,30}[a-z0-9])?$/;
130	export function isValidSubdomainLabel(label: string): boolean {
131	  return SUB_LABEL_RE.test(String(label ?? "").trim().toLowerCase());
132	}
133	
134	/** Docroot + parent dir for a subdomain, jailed under the account home. */
135	export function subdomainPaths(username: string, label: string): { dir: string; docroot: string } {
136	  const dir = `/home/${username}/subdomains/${label}`;
137	  return { dir, docroot: `${dir}/public_html` };
138	}
139	
140	/** Docroot + parent dir for an addon domain, jailed under the account home. */
141	export function addonDomainPaths(username: string, domain: string): { dir: string; docroot: string } {
142	  const dir = `/home/${username}/domains/${domain}`;
143	  return { dir, docroot: `${dir}/public_html` };
144	}
145	
146	/**
147	 * True for a well-formed 5-field cron schedule ("m h dom mon dow"). Each field is
148	 * restricted to the digits/ranges/steps/lists/`*` cron uses — nothing that could
149	 * be a shell metacharacter — so the schedule is safe to write into a crontab.
150	 * (Named shortcuts like @daily are intentionally NOT accepted here.)
151	 */
152	const CRON_FIELD_RE = /^[0-9*/,\-]+$/;
153	export function isValidCronSchedule(schedule: string): boolean {
154	  const parts = String(schedule ?? "").trim().split(/\s+/);
155	  if (parts.length !== 5) return false;
156	  return parts.every((p) => p.length > 0 && p.length <= 40 && CRON_FIELD_RE.test(p));
157	}
158	
159	/**
160	 * True for a cron command safe to place in a crontab line. It runs AS the jailed
161	 * user (crontab -u <user>), so it is already confined; the only invariants we
162	 * enforce here protect our own crontab writer: no newlines (one line per job) and
163	 * no `%` (cron's literal-newline metacharacter), and a sane length.
164	 */
165	export function isValidCronCommand(command: string): boolean {
166	  const c = String(command ?? "");
167	  if (c.length < 1 || c.length > 500) return false;
168	  return !/[\n\r%]/.test(c);
169	}
170	
171	/* ------------------------------------------------------------------------- *
172	 * Provisioner hardening (config generators for NEW accounts)
173	 *
174	 * These are the security-critical config the provisioner writes onto a
175	 * MULTI-TENANT box. They are pure + unit-tested here because a subtle gap in
176	 * any of them (a missing dangerous PHP function, a world-readable webroot, an
177	 * un-escaped GRANT wildcard) is not one customer's bug — it is a cross-tenant
178	 * breach. worker/hosting.ts imports these; it never re-derives them inline.
179	 * ------------------------------------------------------------------------- */
180	
181	/**
182	 * PHP functions blocked in every account's FPM pool (`disable_functions`).
183	 *
184	 * On a shared box `disable_functions` is a real isolation control, not defence
185	 * in depth: without it a tenant's PHP can shell out (`exec`/`system`), fork out
186	 * of `open_basedir` (`pcntl_exec` — compiled into PHP, so it bypasses a naive
187	 * blocklist), rewrite its own env (`putenv` → `LD_PRELOAD`/`GCONV_PATH`
188	 * tricks), plant symlinks that escape the jail (`symlink`/`link`), or reach the
189	 * host via `ffi`/`dl`. Everything a tenant could use to break out of its pool
190	 * belongs here. Kept sorted-by-purpose + deduped.
191	 */
192	export const PHP_DISABLED_FUNCTIONS: readonly string[] = [
193	  // Command execution — the classic RCE surface.
194	  "exec", "passthru", "shell_exec", "system", "proc_open", "popen",
195	  // Process control — pcntl_exec is compiled in and bypasses the above blocklist;
196	  // fork/signal/proc_nice let a tenant escape open_basedir or starve neighbours.
197	  "pcntl_exec", "pcntl_fork", "pcntl_signal", "proc_nice",
198	  // Environment + dynamic loading — putenv enables LD_PRELOAD-style escapes,
199	  // dl/ffi load native code straight past the PHP sandbox.
200	  "putenv", "dl", "ffi",
201	  // Filesystem jail-breaks — symlink/link can point out of open_basedir.
202	  "symlink", "link",
203	  // Misc host-reach / info-leak vectors.
204	  "mail", "error_log", "curl_multi_exec", "parse_ini_file", "show_source",
205	] as const;
206	
207	/** The comma-separated `disable_functions` value for a pool config. */
208	export function phpDisableFunctions(): string {
209	  return [...PHP_DISABLED_FUNCTIONS].join(",");
210	}
211	
212	/**
213	 * Filesystem ownership + permission plan for a new account.
214	 *
215	 * The isolation goal: nginx (www-data) must serve a tenant's files, but a
216	 * NEIGHBOURING tenant (its own jailed unix user) must not be able to read them
217	 * — so nothing here is world-readable (the old `755` webroot let any tenant
218	 * read a peer's wp-config.php if open_basedir was ever escaped).
219	 *
220	 *  - home    `711 root:root` — chroot-safe (root-owned, no group/other write)
221	 *            and world-traversable so nginx can *reach* the webroot, but NOT
222	 *            world-listable, so a peer can't enumerate the home.
223	 *  - webroot `2750 <user>:www-data` — owner (the tenant's FPM pool) read/write,
224	 *            group www-data (nginx) read, world nothing. The setgid bit makes
225	 *            files the tenant creates inherit the www-data group so nginx keeps
226	 *            serving them; peers (neither owner nor in www-data) are shut out.
227	 *  - tmp     `700 <user>:<user>` — private PHP scratch (upload/session dir).
228	 *
229	 * nginx reaches tenant files via GROUP membership (www-data owns the webroot
230	 * group), never via world bits — that is the whole point of dropping 755.
231	 */
232	export function accountFsPlan(username: string): {
233	  home: { owner: string; mode: string };
234	  webroot: { owner: string; mode: string };
235	  tmp: { owner: string; mode: string };
236	  nginxGroup: string;
237	} {
238	  return {
239	    home: { owner: "root:root", mode: "711" },
240	    webroot: { owner: `${username}:www-data`, mode: "2750" },
241	    tmp: { owner: `${username}:${username}`, mode: "700" },
242	    nginxGroup: "www-data",
243	  };
244	}
245	
246	/** PHP-FPM pool hardening limits applied to every account pool. */
247	export const FPM_MEMORY_LIMIT = "256M";
248	export const FPM_REQUEST_TERMINATE_TIMEOUT = "120s";
249	
250	/**
251	 * The per-account PHP-FPM pool config (the PHP isolation boundary). Pure: given
252	 * the validated username + jailed paths, returns the exact pool file contents.
253	 *
254	 * open_basedir is scoped to the account home (+ the shared PHP lib) and NO
255	 * LONGER includes `/tmp`: PHP's tmp/session dirs are redirected into the home,
256	 * so a world-writable `/tmp` on open_basedir was just an unnecessary shared
257	 * surface between tenants. memory_limit + request_terminate_timeout cap a
258	 * single tenant from exhausting the shared box.
259	 */
260	export function fpmPoolConfig(username: string, home: string, webroot: string): string {
261	  const sock = `/run/php/${username}.sock`;
262	  return [
263	    `[${username}]`,
264	    `user = ${username}`,
265	    `group = ${username}`,
266	    `listen = ${sock}`,
267	    `listen.owner = ${username}`,
268	    `listen.group = www-data`,
269	    `pm = ondemand`,
270	    `pm.max_children = 6`,
271	    `pm.process_idle_timeout = 30s`,
272	    `chdir = ${webroot}`,
273	    `php_admin_value[open_basedir] = ${home}:/usr/share/php`,
274	    `php_admin_value[disable_functions] = ${phpDisableFunctions()}`,
275	    `php_admin_value[memory_limit] = ${FPM_MEMORY_LIMIT}`,
276	    `php_admin_value[request_terminate_timeout] = ${FPM_REQUEST_TERMINATE_TIMEOUT}`,
277	    `php_admin_value[upload_tmp_dir] = ${home}/tmp`,
278	    `php_admin_value[session.save_path] = ${home}/tmp`,
279	  ].join("\n");
280	}
281	
282	/**
283	 * Escape a MySQL identifier for the `ON <db>.*` clause of a GRANT.
284	 *
285	 * In GRANT, `_` and `%` are LIKE-wildcards: an un-escaped grant on `nxuser_wp`
286	 * silently also grants on `nxuserXwp`, `nxuser_wpZ`, … i.e. a neighbouring
287	 * tenant's database. Escaping them (and the escape char itself) with a
288	 * backslash pins the grant to exactly one database.
289	 */
290	export function escapeGrantDbName(name: string): string {
291	  return name.replace(/([\\_%])/g, "\\$1");
292	}
293	
294	/**
295	 * The scoped SQL that creates one account database + user and grants that user
296	 * privileges on THAT DATABASE ONLY.
297	 *
298	 * Security invariants (audited): the GRANT is pinned to the exact db via
299	 * escapeGrantDbName (no wildcard bleed into a peer's db), it is NEVER `*.*`,
300	 * and `ALL PRIVILEGES` at database scope confers no global FILE/SUPER (those
301	 * are server-level and cannot be granted by a db-scoped GRANT). Returns plain
302	 * SQL with real backticks; the caller shell-escapes for `mysql -e`.
303	 */
304	export function buildScopedGrantSql(dbName: string, dbUser: string, dbPass: string): string {
305	  const grantName = escapeGrantDbName(dbName);
306	  return (
307	    `CREATE DATABASE IF NOT EXISTS \`${dbName}\`; ` +
308	    `CREATE USER IF NOT EXISTS '${dbUser}'@'localhost' IDENTIFIED BY '${dbPass}'; ` +
309	    `GRANT ALL PRIVILEGES ON \`${grantName}\`.* TO '${dbUser}'@'localhost'; ` +
310	    `FLUSH PRIVILEGES;`
311	  );
312	}
