405	/**
406	 * For each ACTIVE account without HTTPS, once its domain resolves to the node's
407	 * shared IP, issue a per-domain cert (webroot) and upgrade the vhost to a 443 SNI
408	 * block. Safe: touches only nginx + certbot, never sshd.
409	 */
410	export async function hostingSslSweep(): Promise<void> {
411	  if (SANDBOX || !ENABLED) return;
412	  const accts = await db.hostingAccount.findMany({
413	    where: { status: "ACTIVE", sslActive: false },
414	    include: { node: true },
415	    take: 20,
416	  });
417	  for (const a of accts) {
418	    try {
419	      if (!isValidHostingDomain(a.primaryDomain) || !isValidUnixUsername(a.username)) continue;
420	      if (!(await domainPointsAt(a.primaryDomain, a.node.publicIp))) continue; // DNS not pointed yet
421	      const d = a.primaryDomain;
422	      const conn = await connectNode(a.node);
423	      try {
424	        const issue = await exec(conn, `certbot certonly --webroot -w /var/www/html -d ${d} -d www.${d} --allow-subset-of-names --non-interactive --agree-tos --register-unsafely-without-email --keep-until-expiring 2>&1`, 3 * 60_000);
425	        const liveDir = `/etc/letsencrypt/live/${d}`;
426	        const have = await exec(conn, `test -s ${liveDir}/fullchain.pem && echo yes || echo no`);
427	        if (have.out.trim() !== "yes") { console.log(`[hosting] cert for ${d} not issued yet: ${issue.out.slice(0, 160)}`); continue; }
428	        const { webroot } = accountPaths(a.username);
429	        await installVhost(conn, a.username, renderHostingVhost(a.username, d, webroot, `/run/php/${a.username}.sock`, { certDir: liveDir, real: true }));
430	      } finally {
431	        try { conn.end(); } catch { /* */ }
432	      }
433	      await db.hostingAccount.update({ where: { id: a.id }, data: { sslActive: true } });
434	      console.log(`[hosting] HTTPS active for ${a.primaryDomain}`);
435	    } catch (e) {
436	      console.error(`[hosting] ssl sweep ${a.id} failed`, e);
437	    }
438	  }
439	
440	  // Addon domains get their own per-domain cert the same way, once they resolve
441	  // to the node's shared IP. (Subdomains are left for a wildcard-cert follow-up.)
442	  const addons = await db.hostingAddonDomain.findMany({
443	    where: { status: "ACTIVE", sslActive: false },
444	    include: { account: { include: { node: true } } },
445	    take: 20,
446	  });
447	  for (const ad of addons) {
448	    try {
449	      const u = ad.account.username;
450	      const d = ad.domain;
451	      if (!isValidHostingDomain(d) || !isValidUnixUsername(u)) continue;
452	      if (!(await domainPointsAt(d, ad.account.node.publicIp))) continue; // DNS not pointed yet
453	      const conn = await connectNode(ad.account.node);
454	      try {
455	        const issue = await exec(conn, `certbot certonly --webroot -w /var/www/html -d ${d} -d www.${d} --allow-subset-of-names --non-interactive --agree-tos --register-unsafely-without-email --keep-until-expiring 2>&1`, 3 * 60_000);
456	        const liveDir = `/etc/letsencrypt/live/${d}`;
457	        const have = await exec(conn, `test -s ${liveDir}/fullchain.pem && echo yes || echo no`);
458	        if (have.out.trim() !== "yes") { console.log(`[hosting] addon cert for ${d} not issued yet: ${issue.out.slice(0, 160)}`); continue; }
459	        const { docroot } = addonDomainPaths(u, d);
460	        await installNamedVhost(conn, `${u}-${d}`, renderSiteVhost(`${d} www.${d}`, docroot, `/run/php/${u}.sock`, liveDir));
461	      } finally {
462	        try { conn.end(); } catch { /* */ }
463	      }
464	      await db.hostingAddonDomain.update({ where: { id: ad.id }, data: { sslActive: true } });
465	      console.log(`[hosting] HTTPS active for addon ${d}`);
466	    } catch (e) {
467	      console.error(`[hosting] addon ssl sweep ${ad.id} failed`, e);
468	    }
469	  }
470	}
