1	// Shared-hosting file manager over SFTP.
2	//
3	// SECURITY: we connect AS THE JAILED ACCOUNT USER (chrooted internal-sftp), so
4	// the operating-system chroot is the jail — a tenant symlink can never resolve
5	// outside their own tree. Do NOT connect as root here: a lexical path check
6	// cannot stop root's SFTP following a tenant-planted symlink (audit 2026-08-01).
7	// The lexical checks below are defence-in-depth only.
8	
9	import { Client, type SFTPWrapper } from "ssh2";
10	import { decryptSecret } from "./crypto-box";
11	
12	export type HostingFsTarget = { sshHost: string; sshPort: number; username: string; sftpPassword: string };
13	
14	/** Build the chrooted-SFTP target for an account (connects AS the jailed user, so
15	 *  the OS chroot is the jail — never as root, which a symlink can escape).
16	 *  Returns null if the account has no stored SFTP password yet. Lives in this
17	 *  plain module (not the "use server" actions file) because it is synchronous. */
18	export function fsTargetFor(a: { node: { sshHost: string; sshPort: number }; username: string; sftpPasswordEnc: string | null }): HostingFsTarget | null {
19	  const pw = a.sftpPasswordEnc ? decryptSecret(a.sftpPasswordEnc) : null;
20	  if (!pw) return null;
21	  return { sshHost: a.node.sshHost, sshPort: a.node.sshPort, username: a.username, sftpPassword: pw };
22	}
23	export type FsEntry = { name: string; isDir: boolean; size: number; modified: number };
24	
25	const CONNECT_TIMEOUT_MS = 20_000;
26	
27	/** A relative, traversal-free path inside the account chroot. Defence-in-depth:
28	 *  the chroot is the real boundary; this just rejects obviously-bad input. */
29	export function safeRel(relPath: string): string {
30	  const rel = String(relPath ?? "").replace(/\\/g, "/").replace(/^\/+/, "").replace(/\/+/g, "/");
31	  if (!rel) return "public_html";
32	  if (rel.includes("..") || rel.includes("\0")) throw new Error("invalid path");
33	  if (!/^[A-Za-z0-9._/\- ]{1,1024}$/.test(rel)) throw new Error("invalid path chars");
34	  return rel;
35	}
36	
37	async function connect(t: HostingFsTarget): Promise<Client> {
38	  if (!/^[a-z][a-z0-9]{2,31}$/.test(t.username) || !t.sftpPassword) throw new Error("bad account credential");
39	  const conn = new Client();
40	  await new Promise<void>((resolve, reject) => {
41	    const timer = setTimeout(() => { try { conn.end(); } catch { /* */ } reject(new Error("connect timeout")); }, CONNECT_TIMEOUT_MS);
42	    conn.on("ready", () => { clearTimeout(timer); resolve(); })
43	      .on("error", (e) => { clearTimeout(timer); reject(e); })
44	      // Connect as the ACCOUNT USER — the sshd chroot confines the whole session.
45	      .connect({ host: t.sshHost, port: t.sshPort, username: t.username, password: t.sftpPassword, readyTimeout: CONNECT_TIMEOUT_MS });
46	  });
47	  return conn;
48	}
49	
50	function sftpOf(conn: Client): Promise<SFTPWrapper> {
51	  return new Promise((resolve, reject) => conn.sftp((err, sftp) => (err ? reject(err) : resolve(sftp))));
52	}
53	
54	async function withSftp<T>(t: HostingFsTarget, fn: (sftp: SFTPWrapper) => Promise<T>): Promise<T> {
55	  const conn = await connect(t);
56	  try {
57	    return await fn(await sftpOf(conn));
58	  } finally {
59	    try { conn.end(); } catch { /* */ }
60	  }
61	}
62	
63	export async function fsList(t: HostingFsTarget, relPath: string): Promise<FsEntry[]> {
64	  const p = safeRel(relPath);
65	  return withSftp(t, (sftp) => new Promise<FsEntry[]>((resolve, reject) => {
66	    sftp.readdir(p, (err, list) => {
67	      if (err) return reject(err);
68	      resolve(
69	        list
70	          .map((e) => ({ name: e.filename, isDir: (e.attrs.mode & 0o40000) !== 0, size: e.attrs.size, modified: (e.attrs.mtime ?? 0) * 1000 }))
71	          .filter((e) => e.name !== "." && e.name !== "..")
72	          .sort((a, b) => Number(b.isDir) - Number(a.isDir) || a.name.localeCompare(b.name)),
73	      );
74	    });
75	  }));
76	}
77	
78	export async function fsMkdir(t: HostingFsTarget, relPath: string): Promise<void> {
79	  const p = safeRel(relPath);
80	  await withSftp(t, (sftp) => new Promise<void>((resolve, reject) => sftp.mkdir(p, (e) => (e ? reject(e) : resolve()))));
81	}
