91	export async function fsReadBuffer(t: HostingFsTarget, relPath: string): Promise<Buffer> {
92	  const p = safeRel(relPath);
93	  return withSftp(t, (sftp) => new Promise<Buffer>((resolve, reject) => {
94	    const chunks: Buffer[] = [];
95	    const stream = sftp.createReadStream(p);
96	    stream.on("data", (d: Buffer) => chunks.push(d));
97	    stream.on("end", () => resolve(Buffer.concat(chunks)));
98	    stream.on("error", reject);
99	  }));
