978	async function processHostingTask(taskId: string): Promise<void> {
979	  const task = await db.hostingTask.findUnique({ where: { id: taskId }, include: { account: { include: { node: true } } } });
980	  if (!task || task.status !== "PENDING") return;
981	  await db.hostingTask.update({ where: { id: task.id }, data: { status: "RUNNING" } });
982	  const a = task.account;
983	  // Lifecycle tasks deliberately run on a NON-active account: the admin action
984	  // flips status to SUSPENDED / DELETING *before* queuing, so gating them on ACTIVE
985	  // (like the content tasks) would make suspend/terminate silent no-ops — the kill
986	  // switch must still fire. Content tasks (PHP/WP/backup/restore) stay ACTIVE-only.
987	  const isLifecycle = task.kind === "SUSPEND" || task.kind === "UNSUSPEND" || task.kind === "TERMINATE";
988	  if (!isLifecycle && a.status !== "ACTIVE") { await failTask(task.id, "the account is not active"); return; }
989	  try {
990	    const conn = await connectNode(a.node);
991	    try {
992	      let result: string | null = null;
993	      if (task.kind === "PHP_SWITCH") await taskPhpSwitch(conn, a, task.payload);
994	      else if (task.kind === "WORDPRESS_INSTALL") result = await taskWordpressInstall(conn, a, task.payload);
995	      else if (task.kind === "APP_INSTALL") result = await taskAppInstall(conn, a, task.payload);
996	      else if (task.kind === "BACKUP") await taskBackup(conn, a, task.id);
997	      else if (task.kind === "RESTORE") await taskRestore(conn, a, task.payload);
998	      else if (task.kind === "SUSPEND") await taskSuspend(conn, a);
999	      else if (task.kind === "UNSUSPEND") await taskUnsuspend(conn, a);
1000	      else if (task.kind === "TERMINATE") await taskTerminate(conn, a);
1001	      else if (task.kind === "CREATE_SUBDOMAIN") await taskCreateSubdomain(conn, a, task.payload);
1002	      else if (task.kind === "DELETE_SUBDOMAIN") await taskDeleteSubdomain(conn, a, task.payload);
1003	      else if (task.kind === "CREATE_ADDON_DOMAIN") await taskCreateAddonDomain(conn, a, task.payload);
1004	      else if (task.kind === "DELETE_ADDON_DOMAIN") await taskDeleteAddonDomain(conn, a, task.payload);
1005	      else if (task.kind === "CREATE_CRON") await taskCreateCron(conn, a, task.payload);
1006	      else if (task.kind === "DELETE_CRON") await taskDeleteCron(conn, a, task.payload);
1007	      await db.hostingTask.update({ where: { id: task.id }, data: { status: "DONE", result, error: null } });
1008	    } finally { try { conn.end(); } catch { /* */ } }
1009	  } catch (e) {
1010	    await failTask(task.id, (e instanceof Error ? e.message : String(e)).slice(0, 300));
1011	  }
1012	}
