129	      accountId = acct.id;
130	    });
131	  } catch (e) {
132	    return { error: "Couldn’t place the order. Your wallet was not charged — try again." };
133	  }
134	
135	  await db.auditLog.create({ data: { userId: user.id, action: "hosting.order", detail: `${plan.name} · ${name}` } }).catch(() => {});
136	  revalidatePath("/dashboard/hosting");
137	  return { ok: true, accountId };
138	}
