256	/** Create a scoped database for an account (within the plan's maxDatabases). */
257	export async function createHostingDatabase(accountId: string, label: string): Promise<{ error?: string; ok?: boolean; password?: string }> {
258	  const user = await requireUser();
259	  await assertNotImpersonating();
260	  const a = await db.hostingAccount.findUnique({ where: { id: accountId }, select: { id: true, userId: true, status: true, username: true, maxDatabases: true } });
261	  if (!a) return { error: "Account not found." };
262	  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
263	  if (a.status !== "ACTIVE") return { error: "The account is still being set up." };
264	  // A short, safe suffix keyed off the account username: <user>_<slug>.
265	  const slug = String(label ?? "").toLowerCase().replace(/[^a-z0-9]/g, "").slice(0, 12) || "db";
266	  const name = `${a.username}_${slug}`.slice(0, 64);
267	  const dbUser = name.slice(0, 32);
268	  if (!/^[a-z0-9_]{1,64}$/.test(name)) return { error: "Invalid database name." };
269	  const password = randomBytes(12).toString("base64url").replace(/[^A-Za-z0-9]/g, "").slice(0, 20);
270	  // Count + create in ONE serializable transaction, so concurrent creates can't
271	  // both read a stale count and blow past the plan cap (audit 2026-08-01 TOCTOU).
272	  try {
273	    await db.$transaction(async (tx) => {
274	      const n = await tx.hostingDatabase.count({ where: { accountId: a.id, status: { in: ["PENDING", "ACTIVE"] } } });
275	      if (n >= a.maxDatabases) throw new Error("CAP");
276	      await tx.hostingDatabase.create({ data: { accountId: a.id, name, dbUser, passwordEnc: encryptSecret(password), status: "PENDING" } });
277	    }, { isolationLevel: "Serializable" });
278	  } catch (e) {
279	    if (e instanceof Error && e.message === "CAP") return { error: `Your plan allows ${a.maxDatabases} database${a.maxDatabases === 1 ? "" : "s"}.` };
280	    // Serialization conflict (P2034) or the unique(accountId,name) collision.
281	    return { error: "A database with that name already exists, or the request raced — try again." };
282	  }
283	  revalidatePath("/dashboard/hosting");
284	  // Shown ONCE — the encrypted copy is cleared by the provisioner after it applies it.
285	  return { ok: true, password };
286	}
