export async function listHostingTasks(accountId: string): Promise<{ id: string; kind: string; status: string; result: string | null; error: string | null; createdAt: string }[]> {
  const user = await requireUser();
  // A DONE task result can carry a one-time secret (the WordPress admin password);
  // an impersonating admin must not read it out (audit LOW-1, same as reveal above).
  await assertNotImpersonating();
  const a = await db.hostingAccount.findUnique({ where: { id: accountId }, select: { userId: true } });
